<template><div><div class="mb-6"><div class="eyebrow mb-2">Nachvollziehbarkeit</div><h1 class="page-heading">Audit Log</h1><p class="muted mt-2">Wichtige Systemaktionen mit Benutzer, Zeitpunkt und Entität.</p></div><v-card class="surface-card overflow-hidden"><v-skeleton-loader v-if="loading" type="table-heading,table-row@8"/><v-table v-else><thead><tr><th>Zeitpunkt</th><th>Benutzer</th><th>Aktion</th><th>Entität</th><th>Metadaten</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td class="amount">{{dateTime(log.createdAt)}}</td><td>{{log.user?.name??'System'}}</td><td><v-chip size="small" variant="tonal" color="primary">{{action(log.action)}}</v-chip></td><td>{{log.entityType}}<span v-if="log.entityId" class="text-caption muted d-block">{{log.entityId.slice(0,8)}}…</span></td><td><code class="metadata">{{JSON.stringify(log.metadata)}}</code></td></tr></tbody></v-table><v-divider/><v-pagination v-model="page" :length="totalPages" class="pa-3" @update:model-value="load"/></v-card></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{api,apiMessage}from'../api/client';import{useUiStore}from'../stores/ui';interface Log{id:string;createdAt:string;action:string;entityType:string;entityId:string|null;metadata:Record<string,unknown>;user?:{name:string}}const logs=ref<Log[]>([]),loading=ref(true),page=ref(1),totalPages=ref(1),ui=useUiStore();async function load(){loading.value=true;try{const r=await api.get('/audit-logs',{params:{page:page.value,pageSize:25}});logs.value=r.data.data;totalPages.value=r.data.meta.totalPages}catch(e){ui.notify(apiMessage(e),'error')}finally{loading.value=false}}function dateTime(v:string){return new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'medium'}).format(new Date(v))}function action(v:string){return v.replaceAll('_',' ').toLocaleLowerCase('de-DE').replace(/^./,x=>x.toUpperCase())}onMounted(load);</script>
<style scoped>.metadata{display:block;max-width:320px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;background:rgba(var(--v-theme-on-surface),.05);padding:4px 7px;border-radius:6px}</style>
